// mode11_supervisor.v
//
// Mode 11 (ADAPTIVE) closed-loop supervisor for the adaptive multiplier.
//
// Control law (see docs: "steady-state open-loop lookup + periodic
// closed-loop calibration"):
//
//   1. Offline error model: lut_nmed(w) = NMED of approx_mult at width w,
//      exhaustively characterized under uniform operands (supervisor_lut.vh,
//      generated by models/gen_supervisor_lut.py).
//
//   2. Every cycle: find dynamic_ceiling = the largest width
//      w whose drift-corrected predicted error is still inside the budget:
//
//          lut_nmed(w) * drift_estimate  <=  NMED_CEIL
//
//      and clamp the externally requested width ("power pressure") to it:
//
//          width_out = min(desired_width, dynamic_ceiling)
//
//      Implementation: the inequality is rearranged at ELABORATION time into
//      a per-width threshold  drift_estimate <= DRIFT_LIMIT[w], with
//      DRIFT_LIMIT[w] = floor(NMED_CEIL * 2^DRIFT_FRAC / lut_nmed(w)).
//      So the runtime hardware is 2N comparators against constants: no
//      multiplier, no divider in the ceiling scan.
//
//   3. Every CAL_PERIOD valid operations, take ONE calibration sample:
//      approx_mult already outputs both `product` and `exact_product`, so the
//      true error |exact - product| at the current width is available for
//      free (reuses mode 00's exact path, no separate oracle). Convert it to
//      a drift sample
//
//          sample = (|err| / MAXPROD) / lut_nmed(width_out)   [Q.DRIFT_FRAC]
//
//      via ONE multiply by a per-width constant K[w] and a right shift
//      (K[w] precomputed at elaboration -> divider-free).
//
//   4. EMA-damped update (NOT snap-to-sample: snapping was found unstable
//      under single-sample noise in RTL co-simulation):
//
//          drift_estimate += (sample - drift_estimate) >>> DAMPING_SHIFT
//
//      clamped to [DRIFT_MIN, DRIFT_MAX] = [0.125x, 8x] by default.
//
// Fixed-point conventions:
//   - NMED values scaled by NMED_SCALE = 1e6 (integers).
//   - drift_estimate is unsigned Q(DW-DRIFT_FRAC).DRIFT_FRAC; 1.0 == 2^DRIFT_FRAC.
//
// Setting CAL_PERIOD very large (e.g. 1_000_000) disables calibration and
// turns this block into the STATIC / open-loop baseline (LUT ceiling computed
// once, never revisited) used for comparison in tb_mode11_supervisor.v.

`timescale 1ns/1ps

module mode11_supervisor #(
    parameter integer N             = 8,         // operand bit-width
    parameter integer CAL_PERIOD    = 20,        // ops between calibration samples
    parameter integer DAMPING_SHIFT = 3,         // EMA weight = 1/2^DAMPING_SHIFT
    parameter integer NMED_CEIL     = 20000,     // error budget, NMED*1e6 (20000 = 2%)
    parameter integer DRIFT_FRAC    = 8,         // fractional bits of drift_estimate
    parameter integer DRIFT_MIN     = 32,        // 0.125x
    parameter integer DRIFT_MAX     = 2048,      // 8x
    parameter integer DW            = 12,        // drift_estimate register width
    parameter integer K_SHIFT       = 2*N,       // precision of the sample-conversion constant
                                                 // (must scale with the 2N-bit product, else K
                                                 //  underflows to 0 for large N -- seen at N=16)
    parameter integer MW            = 10         // mantissa bits of the conversion constant
) (
    input  wire                    clk,
    input  wire                    rst_n,
    input  wire                    enable,         // 1 when top-level mode == 2'b11
    input  wire                    op_valid,       // a real multiply happens this cycle
    input  wire [$clog2(2*N):0]    desired_width,  // requested width (power pressure)
    input  wire [2*N-1:0]          mult_product,   // approx_mult.product  (at width_out)
    input  wire [2*N-1:0]          mult_exact,     // approx_mult.exact_product
    output reg  [$clog2(2*N):0]    width_out,      // width actually applied
    output reg  [$clog2(2*N):0]    dynamic_ceiling,// largest currently-safe width
    output reg  [DW-1:0]           drift_estimate, // Q.DRIFT_FRAC, 1.0 = 2^DRIFT_FRAC
    output wire                    cal_event       // 1 on cycles where a sample is taken
);

    // Constant tables below intentionally narrow/widen integer parameters.
    /* verilator lint_off WIDTH */
    localparam integer WB      = $clog2(2*N) + 1;
    localparam [63:0]  OPMAX_64 = (64'd1 << N) - 64'd1;
    localparam integer NMED_SCALE = 1000000;
    localparam integer CNT_W   = (CAL_PERIOD > 1) ? $clog2(CAL_PERIOD) : 1;
    localparam integer ONE     = (1 << DRIFT_FRAC);
    localparam [63:0]  NMED_SCALE_64 = NMED_SCALE;
    localparam [63:0]  NMED_CEIL_64  = NMED_CEIL;
    localparam [63:0]  MAXPROD_64    = OPMAX_64 * OPMAX_64;   // 64-bit: no overflow at N=16
    localparam [CNT_W-1:0] CAL_LAST  = CAL_PERIOD - 1;

    // ---- offline error model ----
    `include "supervisor_lut.vh"

    // ---- elaboration-time constant tables (no runtime hardware) ----
    // DRIFT_LIMIT[w]: width w is safe iff drift_estimate <= DRIFT_LIMIT[w]
    function [63:0] drift_limit;
        input integer w;
        reg [63:0] num, den;
        begin
            if (lut_nmed(w) == 0) drift_limit = 64'hFFFF_FFFF;   // width 0: always safe
            else begin
                num = NMED_CEIL_64 << DRIFT_FRAC;
                den = lut_nmed(w);
                drift_limit = num / den;
            end
        end
    endfunction

    // K[w] = round( 2^K_SHIFT * 2^DRIFT_FRAC * NMED_SCALE / (MAXPROD * lut_nmed(w)) )
    // so that  sample_drift = (|err| * K[w]) >> K_SHIFT
    function [63:0] k_const;
        input integer w;
        reg [63:0] num, den;
        begin
            if (lut_nmed(w) == 0) k_const = 0;
            else begin
                num = NMED_SCALE_64 << (K_SHIFT + DRIFT_FRAC);
                den = lut_nmed(w);
                den = den * MAXPROD_64;
                k_const = (num + (den >> 1)) / den;
            end
        end
    endfunction

    // K[w] is stored in floating-point-like form to keep the multiplier
    // small:  K[w] ~= MANT[w] * 2^(K_SHIFT - SH[w]),  MANT normalised to MW
    // bits. Then  sample = (|err| * MANT[w]) >> SH[w].
    // (relative precision 2^-(MW-1), i.e. ~0.2% for MW = 10)
    function integer k_exp;                     // E = number of bits K exceeds MW by
        input integer w;
        reg [63:0] kv;
        integer e;
        begin
            kv = k_const(w);
            e  = 0;
            while ((kv >> e) >= (64'd1 << MW)) e = e + 1;
            k_exp = e;
        end
    endfunction
    function [63:0] k_mant;
        input integer w;
        reg [63:0] kv;
        integer e;
        begin
            kv = k_const(w);
            e  = k_exp(w);
            if (e == 0) k_mant = kv;
            else        k_mant = (kv + (64'd1 << (e - 1))) >> e;   // round
            if (k_mant >= (64'd1 << MW)) k_mant = (64'd1 << MW) - 1;
        end
    endfunction
    function integer k_sh;
        input integer w;
        begin
            k_sh = K_SHIFT - k_exp(w);
        end
    endfunction

    localparam integer EW  = 2*N + 1;                // |err| width (incl. headroom)
    localparam integer PW  = EW + MW;                // mantissa-product width
    localparam integer SHW = $clog2(K_SHIFT + 1);    // shift-amount width

    /* verilator lint_on WIDTH */

    // ------------------------------------------------------------------
    // (2) combinational ceiling scan + clamp
    // ------------------------------------------------------------------
    // The scan result is registered: dynamic_ceiling only changes when
    // drift_estimate changes (at most once per CAL_PERIOD ops), so a 1-cycle
    // delay costs nothing and keeps the scan off the datapath critical path.
    // After reset it starts at 0 (exact) for one cycle, which is always safe.
    reg [WB-1:0] ceil_comb;
    integer w;
    always @(*) begin
        ceil_comb = {WB{1'b0}};
        for (w = 0; w < 2*N; w = w + 1) begin
            if ({{(64-DW){1'b0}}, drift_estimate} <= drift_limit(w))
                ceil_comb = w[WB-1:0];
        end
    end

    always @(*) begin
        width_out = (desired_width < dynamic_ceiling) ? desired_width : dynamic_ceiling;
    end

    // ------------------------------------------------------------------
    // (3) calibration scheduling: one sample every CAL_PERIOD valid ops
    // ------------------------------------------------------------------
    reg [CNT_W-1:0] cal_cnt;
    wire cal_slot = enable && op_valid && (cal_cnt == CAL_LAST);
    // width 0 carries no error information (exact) -> skip the update
    assign cal_event = cal_slot && (width_out != 0);

    // ---- calibration sample: |err| at the current width ----
    wire [EW-1:0] err_abs = (mult_exact >= mult_product)
                          ? {1'b0, mult_exact - mult_product}
                          : {1'b0, mult_product - mult_exact};

    // ---- per-width conversion constant, selected by width_out ----
    reg [MW-1:0]   m_sel;
    reg [SHW-1:0]  sh_sel;
    /* verilator lint_off UNUSEDSIGNAL */
    reg [63:0]     m_tmp;             // only the low MW bits are ever non-zero
    reg [31:0]     sh_tmp;            // only the low SHW bits are ever non-zero
    /* verilator lint_on UNUSEDSIGNAL */
    integer kw;
    always @(*) begin
        m_sel  = {MW{1'b0}};
        sh_sel = {SHW{1'b0}};
        m_tmp  = 64'd0;
        sh_tmp = 32'd0;
        for (kw = 1; kw < 2*N; kw = kw + 1) begin
            if (width_out == kw[WB-1:0]) begin
                m_tmp  = k_mant(kw);
                m_sel  = m_tmp[MW-1:0];
                sh_tmp = k_sh(kw);
                sh_sel = sh_tmp[SHW-1:0];
            end
        end
    end

    // ---- serial (shift-add) conversion:  sample = (|err| * MANT) >> SH ----
    // Calibration happens only once every CAL_PERIOD operations, so the
    // multiply does not need to be fast: it is done bit-serially over MW
    // cycles with ONE adder instead of a full array multiplier. This keeps
    // the supervisor small and keeps the calibration arithmetic completely
    // off the datapath's critical path. Requires CAL_PERIOD > MW + 1
    // (a sample arriving while the previous one is still being processed
    // is dropped).
    localparam integer CW = $clog2(MW + 1);
    reg            busy;
    reg [CW-1:0]   bit_cnt;
    reg [PW-1:0]   acc;
    reg [PW-1:0]   mcand;
    reg [MW-1:0]   mplier;
    reg [SHW-1:0]  sh_q;

    wire [PW-1:0] sample_raw = acc >> sh_q;

    // elaboration-time guard: fails to elaborate (unknown module) if violated
    generate
        if (CAL_PERIOD <= MW + 1) begin : g_bad_cal_period
            ERROR_CAL_PERIOD_must_exceed_MW_plus_1 u_err ();
        end
    endgenerate

    // clamp the raw sample to DRIFT_MAX before the EMA so the update path
    // stays narrow (a single huge sample can still only move the estimate
    // by (DRIFT_MAX - drift)/2^DAMPING_SHIFT in one step)
    /* verilator lint_off WIDTH */
    localparam [PW-1:0]       DMAX_P = DRIFT_MAX;
    localparam [DW-1:0]       DMAX_D = DRIFT_MAX;
    localparam [DW-1:0]       DMIN_D = DRIFT_MIN;
    localparam signed [DW+1:0] DMAX_S = DRIFT_MAX;
    localparam signed [DW+1:0] DMIN_S = DRIFT_MIN;
    /* verilator lint_on WIDTH */
    wire [DW-1:0] sample_c = (sample_raw > DMAX_P) ? DMAX_D : sample_raw[DW-1:0];

    // ---- (4) EMA update: one subtract + one arithmetic shift ----
    // (applied once the serial conversion above has finished)
    wire signed [DW+1:0] diff      = $signed({2'b00, sample_c}) - $signed({2'b00, drift_estimate});
    wire signed [DW+1:0] step      = diff >>> DAMPING_SHIFT;
    wire signed [DW+1:0] drift_nxt = $signed({2'b00, drift_estimate}) + step;

    wire [DW-1:0] drift_clamped =
        (drift_nxt < DMIN_S) ? DMIN_D :
        (drift_nxt > DMAX_S) ? DMAX_D :
                                  drift_nxt[DW-1:0];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cal_cnt        <= {CNT_W{1'b0}};
            drift_estimate <= ONE[DW-1:0];          // start trusting the LUT (1.0x)
            busy           <= 1'b0;
            bit_cnt        <= {CW{1'b0}};
            acc            <= {PW{1'b0}};
            mcand          <= {PW{1'b0}};
            mplier         <= {MW{1'b0}};
            sh_q           <= {SHW{1'b0}};
            dynamic_ceiling <= {WB{1'b0}};
        end else begin
            dynamic_ceiling <= ceil_comb;
            if (enable && op_valid) begin
                if (cal_cnt == CAL_LAST)
                    cal_cnt <= {CNT_W{1'b0}};
                else
                    cal_cnt <= cal_cnt + 1'b1;
            end

            if (!busy) begin
                // capture one sample
                if (cal_event) begin
                    busy    <= 1'b1;
                    bit_cnt <= MW[CW-1:0];
                    acc     <= {PW{1'b0}};
                    mcand   <= {{(PW-EW){1'b0}}, err_abs};
                    mplier  <= m_sel;
                    sh_q    <= sh_sel;
                end
            end else if (bit_cnt != 0) begin
                // one shift-add step per cycle
                if (mplier[0]) acc <= acc + mcand;
                mcand   <= mcand << 1;
                mplier  <= mplier >> 1;
                bit_cnt <= bit_cnt - 1'b1;
            end else begin
                // EMA update from the finished sample
                drift_estimate <= drift_clamped;
                busy           <= 1'b0;
            end
        end
    end

endmodule
